function AdminFiles() {
  const data = useWorkspaceDemo(); const [projectId, setProjectId] = useState(""); const [message, setMessage] = useState("");
  function choose(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const file = (form.querySelector<HTMLInputElement>("input[name=file]")?.files)?.[0]; if (!file) return; data.addFile(projectId, file); setMessage("Local file preview ready. It has not been uploaded."); form.reset(); }
  return <><PageHeading eyebrow="Storage" title="Files" description="Create browser-only previews for files you select. They are not uploaded, shared, or access-controlled." /><form className="file-pick-form" onSubmit={choose}><label className="workspace-field">Project<select onChange={(event) => setProjectId(event.target.value)} value={projectId}><option value="">Unassigned</option>{data.projects.map((x) => <option key={x.id} value={x.id}>{x.title}</option>)}</select></label><label className="workspace-field">Choose a file<input accept="*/*" name="file" required type="file" /></label><button className="button button-gold" type="submit"><Upload size={15} />Add local preview</button></form><FormStatus message={message} /><section className="module-panel"><h3>Current session files</h3>{data.files.map((file) => <FileRow file={file} key={file.id} onRemove={() => data.removeFile(file.id)} />)}{!data.files.length && <EmptyState title="No file previews" description="Choose a file above to preview it locally in this browser session." />}</section></>;
}

